package com.omnibank.automation.runners;

import io.cucumber.testng.AbstractTestNGCucumberTests;
import io.cucumber.testng.CucumberOptions;

/**
 * Reads reports/failed_scenarios.txt (auto-generated by TestRunner's "rerun:" plugin)
 * and re-executes ONLY those scenarios. This is the standard Cucumber way to rerun
 * failures as a second pass - typically wired as a separate Jenkins pipeline stage
 * that only runs if the first run reported failures.
 *
 * Usage:
 *   mvn test -Dtest=RerunFailedTests
 */
@CucumberOptions(
        features = "@reports/failed_scenarios.txt",
        glue = {"com.omnibank.automation.stepdefinitions"},
        plugin = {
                "pretty",
                "html:reports/rerun-report.html",
                "com.aventstack.extentreports.cucumber.adapter.ExtentCucumberAdapter:"
        },
        monochrome = true
)
public class RerunFailedTests extends AbstractTestNGCucumberTests {
}
